/**
 * GitHub Copilot CLI (`copilot`), the local headless CLI and not the cloud coding
 * agent. `-p` runs one prompt; `--allow-all-tools` is what lets it run without
 * asking for approval at each tool.
 */
import { withoutModelFlag, } from "../harness.js";
export class CopilotHarness {
    id = "copilot";
    displayName = "GitHub Copilot CLI";
    profile = { bin: "copilot", args: [] };
    systemPrompt = false;
    nativeAgent = false;
    confinable = false;
    build({ bin, args }, req) {
        const argv = [bin, ...(req.model ? withoutModelFlag(args) : args)];
        if (req.model)
            argv.push("--model", req.model);
        if (req.prompt !== undefined)
            argv.push("--allow-all-tools", "-p", req.prompt);
        return { argv };
    }
}
